#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, N, DEFINE_PROTO_STRUCT, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "trisolv.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// L is N x N, indexed as L[i][j] in C
	// We use row-major layout: inner dimension 'j', outer 'i'
	DEFINE_PROTO_STRUCT(L_layout, j_vec ^ i_vec);

	// x and b are 1D vectors over 'i'
	DEFINE_PROTO_STRUCT(x_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// Array initialization
// Original C prototype:
//   void init_array(int n, DATA_TYPE L[n][n], DATA_TYPE x[n], DATA_TYPE b[n])
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// Problem size from the structure
	std::size_t n = x | get_length<'i'>();

	// For each i:
	//   x[i] = -999;
	//   b[i] = i;
	//   for (j = 0; j <= i; j++)
	//     L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
	traverser(x, b, L).template for_dims<'i'>([=](auto trav_i) {
		// state for this i
		auto s_i = trav_i.state();
		auto i_idx = get_index<'i'>(s_i);

		// x[i] = -999;
		x[s_i] = static_cast<num_t>(-999);

		// b[i] = i;
		x[s_i]; // keep x[s_i] evaluated, no-op line just to mirror structure
		b[s_i] = static_cast<num_t>(i_idx);

		// View of row i of L, for columns j = 0..i
		auto row_L = L.get_ref()
			^ fix<'i'>(i_idx)
			^ slice<'j'>(std::size_t(0), i_idx + 1);

		// Iterate j from 0 to i (via the slice)
		traverser(row_L).for_each([=](auto s_j) {
			auto j_idx = get_index<'j'>(s_j);
			// integer arithmetic as in the original C code
			auto num = (i_idx + n - j_idx + 1) * 2;
			num_t value = static_cast<num_t>(num / n);
			row_L[s_j] = value;
		});
	});
}

// Main computational kernel
// Original C kernel:
//
// for (i = 0; i < _PB_N; i++) {
//   x[i] = b[i];
//   for (j = 0; j < i; j++)
//     x[i] -= L[i][j] * x[j];
//   x[i] = x[i] / L[i][i];
// }
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

#pragma scop
	traverser(L, x, b).template for_dims<'i'>([=](auto trav_i) {
		// Fixed i for this iteration
		auto s_i = trav_i.state();
		auto i_idx = get_index<'i'>(s_i);

		// x[i] = b[i];
		x[s_i] = b[s_i];

		// Row view of L for this i, columns j = 0..i-1
		auto row_L = L.get_ref()
			^ fix<'i'>(i_idx)
			^ slice<'j'>(std::size_t(0), i_idx);

		// for (j = 0; j < i; j++)
		//   x[i] -= L[i][j] * x[j];
		traverser(row_L).for_each([=](auto s_j) {
			auto j_idx = get_index<'j'>(s_j);

			num_t lij = row_L[s_j];                  // L[i][j]
			num_t xj  = x[noarr::idx<'i'>(j_idx)];   // x[j]

			x[s_i] -= lij * xj;
		});

		// x[i] = x[i] / L[i][i];
		auto diag_state = s_i.template with<noarr::index_in<'j'>>(i_idx);
		x[s_i] = x[s_i] / L[diag_state];
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Common length settings
	auto set_lengths =
		noarr::set_length<'i'>(n)
		^ noarr::set_length<'j'>(n);

	// Allocate bags for L, x, b
	auto L = noarr::bag(noarr::scalar<num_t>() ^ tuning.L_layout ^ set_lengths);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// Initialize arrays
	init_array(L.get_ref(), x.get_ref(), b.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_trisolv(L.get_ref(), x.get_ref(), b.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print result (and thus prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

