//     L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
// }
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// Retrieve problem size from the structure (length in 'i')
	const std::size_t n = L | get_length<'i'>();

	// Outer loop over i
	traverser(L, x, b).template for_dims<'i'>([=](auto t_i) {
		auto state_i = t_i.state();
		const std::size_t i = get_index<'i'>(state_i);

		// x[i] = -999;
		x[state_i] = (num_t)-999;

		// b[i] = i;
		b[state_i] = (num_t)i;

		// Inner loop over j
