			auto state_ij = t_ij.state();
			const std::size_t j = get_index<'j'>(state_ij);

			// Only fill the lower triangle: j <= i
			if (j <= i) {
				// Integer arithmetic as in the original C code:
				// (i + n - j + 1) * 2 / n, then cast to DATA_TYPE
				const num_t value =
					(num_t)(((i + n - j + 1) * 2) / n);

				L[state_ij] = value;
			}
		});
	});
