#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "trisolv.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// L is N x N (i x j), row-major: j inner, i outer
	DEFINE_PROTO_STRUCT(L_layout, j_vec ^ i_vec);
	// x and b are 1D vectors over i
	DEFINE_PROTO_STRUCT(vec_layout, i_vec);
} tuning;

// initialization function
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// n is the length in the 'i' dimension
	auto n = L | get_length<'i'>();

	// Initialize x[i] and b[i]
	traverser(x, b).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = (num_t)-999;
		b[state] = (num_t)i;
	});

	// Initialize lower-triangular matrix L
	traverser(L).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j <= i) {
			L[state] = (num_t)(i + n - j + 1) * (num_t)2 / (num_t)n;
		}
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

	// Solve L * x = b for x, forward substitution
	#pragma scop
	traverser(x, b, L).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed
		auto state_i = trav_i.state(); // contains 'i' only

		// x[i] = b[i];
		x[state_i] = b[state_i];

		auto i_index = get_index<'i'>(state_i);

		// for (j = 0; j < i; j++)
		trav_i.order(noarr::slice<'j'>(0, i_index)).for_each([&](auto state_ij) {
			// state_ij has 'i' and 'j'
			auto j_index = get_index<'j'>(state_ij);

			// x[j] -> dimension 'i' indexed by j_index
			auto state_j = noarr::idx<'i'>(j_index);

			x[state_i] -= L[state_ij] * x[state_j];
		});

		// x[i] = x[i] / L[i][i];
		auto state_ii = noarr::idx<'i', 'j'>(i_index, i_index);
		x[state_i] = x[state_i] / L[state_ii];
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// common length settings for all structures
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// data structures:
	// L: i x j (N x N)
	auto L = noarr::bag(noarr::scalar<num_t>() ^ tuning.L_layout ^ set_lengths);
	// x: i (N)
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	// b: i (N)
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);

	// initialize data
	init_array(L.get_ref(), x.get_ref(), b.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trisolv(L.get_ref(), x.get_ref(), b.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (live-out data)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// x is 1D over 'i'; hoist<'i'> is a no-op but keeps the pattern
		noarr::serialize_data(std::cerr, x.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
