#include "trisolv.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// L is an N x N matrix, indexed as L[i][j]
	DEFINE_PROTO_STRUCT(L_layout, j_vec ^ i_vec);
} tuning;

// Array initialization.
// L: i x j  (lower triangular is initialized, others are ignored)
// x: i
// b: i
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// n is the problem size (length in 'i')
	auto n = L | get_length<'i'>();

	// Iterate over rows i of L (and indices of x, b)
	traverser(L).template for_dims<'i'>([=](auto trav_i) {
		// State with fixed 'i'
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		// x[i] = -999
		x[state_i] = (num_t)-999;

		// b[i] = i
		b[state_i] = (num_t)i;

		// Initialize L[i][j] for j in [0, i] (lower triangular including diagonal)
		trav_i
			.order(noarr::slice<'j'>(0, i + 1))
			.template for_each<'j'>([=](auto state_ij) {
				auto [ii, jj] = get_indices<'i', 'j'>(state_ij);
				L[state_ij] = (num_t)((ii + n - jj + 1) * 2) / (num_t)n;
			});
	});
}

// Main computational kernel.
// Solves L * x = b for x, where L is lower triangular.
// L: i x j
// x: i
// b: i
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

	#pragma scop
	traverser(L).template for_dims<'i'>([=](auto trav_i) {
		// State with fixed 'i'
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		// x[i] = b[i]
		x[state_i] = b[state_i];

		// For j from 0 to i-1: x[i] -= L[i][j] * x[j]
		trav_i
			.order(noarr::slice<'j'>(0, i))
			.template for_each<'j'>([=](auto state_ij) {
				auto j = get_index<'j'>(state_ij);

				// State for x[j] (1D vector over 'i')
				auto state_j = noarr::idx<'i'>(j);

				x[state_i] -= L[state_ij] * x[state_j];
			});

		// x[i] = x[i] / L[i][i]
		auto state_ii = noarr::idx<'i', 'j'>(i, i);
		x[state_i] = x[state_i] / L[state_ii];
	});
	#pragma endscop
}

} // namespace

