	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// set lengths for all relevant dimensions
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// data structures
	auto L = noarr::bag(noarr::scalar<num_t>() ^ tuning.L_layout ^ set_lengths); // N x N
	auto x = noarr::bag(noarr::scalar<num_t>() ^ i_vec ^ set_lengths);           // N
	auto b = noarr::bag(noarr::scalar<num_t>() ^ i_vec ^ set_lengths);           // N

	// initialize data
	init_array(L.get_ref(), x.get_ref(), b.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trisolv(L.get_ref(), x.get_ref(), b.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (if requested)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

